import { uuid, text, timestamp, integer, numeric } from "drizzle-orm/pg-core";
import { bhiSchema } from "./bhi/_schema";
import { bhiMemberTable } from "./bhi/member";

/**
 * An employee discount coupon, and its redemption at a partner's till.
 *
 * Generated by the member from a live card session for one brand, shown as a
 * QR code, and redeemed once by that brand's POS through /v1/pos/coupons. The
 * row moves ACTIVE → REDEEMED (→ VOIDED if the till reverses the sale), or
 * ACTIVE → CANCELLED when the member generates a newer coupon for the same
 * brand. An ACTIVE row past expires_at is simply expired; nothing rewrites it.
 *
 * Only REDEEMED rows count against the member's monthly allowance, by
 * redeemed_at in Guyana time (lib/discounts.ts). A VOIDED row keeps its bill
 * and discount for the record but gives the allowance back.
 *
 * The code itself is never stored — only its sha256, as with OTP codes and
 * card tokens.
 */
export const discountCouponsTable = bhiSchema.table("discount_coupons", {
  id: uuid("id").primaryKey().defaultRandom(),

  /** The member it was generated for (bhi.member). */
  memberRef: integer("member_ref")
    .notNull()
    .references(() => bhiMemberTable.memberId),
  /** The member's company at generation, for the audit trail and reporting. */
  companyNumber: text("company_number").notNull(),

  brand: text("brand", { enum: ["KFC", "PIZZA_HUT"] }).notNull(),
  codeHash: text("code_hash").notNull().unique(),
  /** The rate in force when it was generated; a later rate change does not reach it. */
  discountPercent: numeric("discount_percent", { precision: 5, scale: 2 }).notNull(),

  status: text("status", { enum: ["ACTIVE", "REDEEMED", "VOIDED", "CANCELLED"] })
    .notNull()
    .default("ACTIVE"),
  expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),

  // --- redemption (set by the POS) -------------------------------------------
  redeemedAt: timestamp("redeemed_at", { withTimezone: true }),
  /** The bill before discount, GYD. */
  billAmount: numeric("bill_amount", { precision: 15, scale: 2 }),
  /** The discount actually given, GYD — capped by what was left of the month's allowance. */
  discountAmount: numeric("discount_amount", { precision: 15, scale: 2 }),
  /** The till's own receipt or order number; makes a retried redeem idempotent. */
  posReference: text("pos_reference"),
  /** Which store or till, as the POS names it. Free text. */
  posStore: text("pos_store"),

  // --- void ------------------------------------------------------------------
  voidedAt: timestamp("voided_at", { withTimezone: true }),
  voidReason: text("void_reason"),

  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

export type DiscountCoupon = typeof discountCouponsTable.$inferSelect;
